-- M2: organizations, machines, enrollment, agent sessions, and events.
--
-- IDs are UUIDs (hyphenated text), timestamps are UTC ISO 8601 text with a
-- fixed width so they sort correctly, and JSON is text. All are generated by
-- the server, so both backends store the same values.

CREATE TABLE organizations (
    id         TEXT PRIMARY KEY NOT NULL,
    name       TEXT NOT NULL UNIQUE,
    created_at TEXT NOT NULL
);

CREATE TABLE machines (
    id               TEXT PRIMARY KEY NOT NULL,
    organization_id  TEXT NOT NULL REFERENCES organizations (id),
    name             TEXT NOT NULL,
    created_at       TEXT NOT NULL,
    -- Set when an enrollment token is redeemed; NULL until then.
    enrolled_at      TEXT,
    -- SHA-256 (hex) of the agent's long-lived credential.
    credential_hash  TEXT UNIQUE,
    agent_version    TEXT,
    facts            TEXT,
    facts_updated_at TEXT,
    last_seen_at     TEXT,
    UNIQUE (organization_id, name)
);

CREATE TABLE enrollment_tokens (
    id         TEXT PRIMARY KEY NOT NULL,
    machine_id TEXT NOT NULL REFERENCES machines (id) ON DELETE CASCADE,
    -- SHA-256 (hex) of the one-time token; the token itself is not stored.
    token_hash TEXT NOT NULL UNIQUE,
    created_at TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    used_at    TEXT
);

CREATE TABLE agent_sessions (
    id                TEXT PRIMARY KEY NOT NULL,
    machine_id        TEXT NOT NULL REFERENCES machines (id) ON DELETE CASCADE,
    agent_version     TEXT NOT NULL,
    connected_at      TEXT NOT NULL,
    last_heartbeat_at TEXT NOT NULL,
    disconnected_at   TEXT,
    disconnect_reason TEXT
);

CREATE INDEX agent_sessions_open ON agent_sessions (machine_id)
    WHERE disconnected_at IS NULL;

CREATE TABLE events (
    id              TEXT PRIMARY KEY NOT NULL,
    organization_id TEXT NOT NULL REFERENCES organizations (id),
    machine_id      TEXT REFERENCES machines (id) ON DELETE SET NULL,
    kind            TEXT NOT NULL,
    data            TEXT NOT NULL,
    created_at      TEXT NOT NULL
);

CREATE INDEX events_machine ON events (machine_id, created_at);
